import {
  BGC, MIcon, Card, CoinChip, PrimaryBtn, SectionLabel, WaterBar,
  MoistureDots, Chip, WanderingBangulee,
} from './ui.jsx'
import { COSTUMES, ROOM_THEMES, CleanImg, RoomWindow } from './ShopScreen.jsx'

const DECOR_POS = {
  // 벽 (top 110~270)
  garland:   { left: 78,  top: 110 },
  mobile:    { left: 258, top: 116 },
  frame:     { left: 12,  top: 212 },
  shelf:     { left: 250, top: 238 },
  // 바닥 왼쪽
  floorlamp: { left: 4,   top: 292 },
  monstera:  { left: 4,   top: 372 },
  cactus:    { left: 66,  top: 398 },
  tulip:     { left: 10,  top: 438 },
  beanbag:   { left: 40,  top: 446 },
  teddy:     { left: 100, top: 452 },
  starlamp:  { left: 58,  top: 300 },
  // 바닥 오른쪽
  dresser:   { left: 250, top: 366 },
  mintlamp:  { left: 262, top: 300 },
  table:     { left: 250, top: 436 },
  pinklamp:  { left: 292, top: 398 },
  stool:     { left: 206, top: 452 },
  ottoman:   { left: 300, top: 456 },
  mirror:    { left: 302, top: 300 },
  wbasket:   { left: 300, top: 414 },
  books:     { left: 214, top: 320 },
  // 중앙 앞
  toybox:    { left: 150, top: 462 },
  basket:    { left: 112, top: 452 },
  cushion:   { left: 176, top: 474 },
  alarm:     { left: 132, top: 320 },
};
const DECOR_MIN_TOP = 108; // 말풍선 아래로만 배치 가능

function DraggableDecor({ id, src, size, initial, roomRef, onEnd }) {
  const [pos, setPos] = useState(initial);
  const [drag, setDrag] = useState(false);
  const start = useRef(null);
  const last = useRef(null);
  useEffect(() => { if (!start.current) setPos(initial); }, [initial.left, initial.top]);
  const clamp = (left, top) => {
    const room = roomRef.current;
    const w = room ? room.clientWidth : 376;
    const h = room ? room.clientHeight : 520;
    const s = size + 6;
    return {
      left: Math.max(4, Math.min(left, w - s)),
      top: Math.max(DECOR_MIN_TOP, Math.min(top, h - s - 42)),
    };
  };
  const onDown = (e) => {
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch (err) {}
    start.current = { px: e.clientX, py: e.clientY, left: pos.left, top: pos.top };
    last.current = pos;
    setDrag(true);
  };
  const onMove = (e) => {
    if (!start.current) return;
    const np = clamp(start.current.left + (e.clientX - start.current.px), start.current.top + (e.clientY - start.current.py));
    last.current = np;
    setPos(np);
  };
  const onUp = () => {
    if (!start.current) return;
    start.current = null;
    setDrag(false);
    if (last.current) onEnd(id, last.current);
  };
  return (
    <div onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
      style={{ position: 'absolute', left: pos.left, top: pos.top, cursor: drag ? 'grabbing' : 'grab', touchAction: 'none', userSelect: 'none', zIndex: drag ? 30 : 6, transform: drag ? 'scale(1.12)' : 'none', transition: drag ? 'none' : 'transform .15s', filter: 'drop-shadow(0 ' + (drag ? 6 : 3) + 'px ' + (drag ? 9 : 5) + 'px rgba(0,0,0,0.25))' }}>
      <img src={src} alt="" draggable={false} style={{ height: size, width: 'auto', display: 'block', pointerEvents: 'none' }}></img>
    </div>
  );
}

function ClosetSheet({ owned, equipped, onEquip, onClose, onNav }) {
  const ownedCostumes = COSTUMES.filter((c) => owned.includes(c.id));
  return (
    <div onClick={onClose} style={{
      position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(20,45,65,0.45)',
      display: 'flex', flexDirection: 'column', justifyContent: 'flex-end',
    }}>
      <div className="sheet-up" onClick={(e) => e.stopPropagation()} style={{
        background: '#fff', borderRadius: '24px 24px 0 0', padding: '14px 18px 26px', maxHeight: '78%', overflowY: 'auto',
      }}>
        <div style={{ width: 40, height: 4, borderRadius: 99, background: '#D9E7F2', margin: '0 auto 12px' }}></div>
        <div style={{ display: 'flex', alignItems: 'center', marginBottom: 14 }}>
          <span className="jua" style={{ flex: 1, fontSize: 19, color: BGC.ink }}>방울이 옷장</span>
          <button className="press" onClick={onClose} style={{ background: '#F1F7FC', border: 'none', borderRadius: 10, width: 34, height: 34, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
            <MIcon name="close" size={19} color={BGC.sub}></MIcon>
          </button>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 10 }}>
          <button className="press" onClick={() => onEquip(null)} style={{
            background: !equipped ? '#EAF5FD' : '#fff', border: !equipped ? `2px solid ${BGC.skyDeep}` : `2px solid ${BGC.line}`,
            borderRadius: 16, padding: '10px 6px', cursor: 'pointer', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6,
          }}>
            <div style={{ height: 70, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <img src="data:image/png;base64," alt="기본" style={{ height: 64 }}></img>
            </div>
            <span style={{ fontSize: 12, fontWeight: 800, color: !equipped ? BGC.skyDeep : BGC.sub }}>기본 모습</span>
          </button>
          {ownedCostumes.map((c) => {
            const on = equipped === c.id;
            return (
              <button key={c.id} className="press" onClick={() => onEquip(c.id)} style={{
                background: on ? '#E8F6EF' : '#fff', border: on ? '2px solid #6FC59A' : `2px solid ${BGC.line}`,
                borderRadius: 16, padding: '10px 6px', cursor: 'pointer', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6,
              }}>
                <div style={{ height: 74, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <img src={c.img} alt={c.name} style={{ maxHeight: 72, maxWidth: 60, objectFit: 'contain' }}></img>
                </div>
                <span style={{ fontSize: 11.5, fontWeight: 800, color: on ? '#2C8A60' : BGC.ink, textAlign: 'center', lineHeight: 1.25 }}>{c.name.replace(' 세트', '')}</span>
              </button>
            );
          })}
        </div>
        <button className="press" onClick={() => { onClose(); onNav('shop'); }} style={{
          width: '100%', marginTop: 14, minHeight: 48, borderRadius: 16, cursor: 'pointer',
          background: '#fff', border: `2px solid ${BGC.line}`, color: BGC.skyDeep,
          fontFamily: 'Jua', fontSize: 15, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 7,
        }}>
          <MIcon name="storefront" size={19} color={BGC.skyDeep}></MIcon>
          상점에서 새 옷 보기
        </button>
      </div>
    </div>
  );
}

function HomeScreen({ app }) {
  const { stage, recorded, usage, goal, coins, streak, tip, house, userName, dolphinName, onNav, onManual, onEditToday, wornImg, sprite, frames, faces, owned, equipped, onEquip, placedItems, decorPos, onMoveDecor, room } = app;
  const roomRef = useRef(null);
  const themeKey = room && room.theme ? room.theme : null;
  const theme = themeKey && ROOM_THEMES[themeKey] ? ROOM_THEMES[themeKey] : null;
  const themeBg = theme ? theme.bg : null;
  const darkRoom = themeKey === 'night';
  const BAR_SKIN = {
    wood:  { bg: 'rgba(252,228,198,0.86)', ink: '#6B4A28' },
    green: { bg: 'rgba(228,231,184,0.86)', ink: '#4B6A32' },
    night: { bg: 'rgba(17,29,55,0.68)',    ink: '#EAF1FF' },
    pink:  { bg: 'rgba(254,220,205,0.86)', ink: '#B24A57' },
  };
  const barSkin = (themeKey && BAR_SKIN[themeKey]) ? BAR_SKIN[themeKey] : { bg: 'rgba(255,255,255,0.82)', ink: BGC.ink };
  const [editMode, setEditMode] = useState(false);
  const st = BG.STAGES[stage - 1];
  const e = BG.energyOf(usage);
  const moisture = Math.max(1, 6 - stage);
  const [closet, setCloset] = useState(false);
  useEffect(() => { if (app.startEdit) { setEditMode(true); app.clearStartEdit && app.clearStartEdit(); } }, [app.startEdit]);

  return (
    <div data-screen-label="홈" className="fade-up" style={{ padding: '6px 18px 100px' }}>
      {/* 헤더 */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 2px 12px' }}>
        <div style={{ flex: 1, display: 'flex', alignItems: 'baseline', gap: 8 }}>
          <span className="jua" style={{ fontSize: 24, color: BGC.ink }}>{(dolphinName || '방울이')}네</span>
          <span style={{ fontSize: 12.5, fontWeight: 700, color: BGC.sub }}>{userName ? userName + ' · ' : ''}{house} 가구</span>
        </div>
        <CoinChip n={coins}></CoinChip>
        <button className="press" onClick={() => onNav('settings')} aria-label="설정" style={{ background: '#fff', border: `1.5px solid ${BGC.line}`, borderRadius: 12, width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
          <MIcon name="settings" size={20} color={BGC.sub} fill={0}></MIcon>
        </button>
      </div>

      {/* 방울이 방 */}
      <div ref={roomRef} style={{
        position: 'relative', borderRadius: 26, overflow: 'hidden', minHeight: 520,
        background: theme ? theme.wall : 'linear-gradient(180deg, #DCEAF6 0%, #E9F2FA 58%, #E7D2AC 58%, #DCC399 100%)',
        border: '1.5px solid #CBE6F8', display: 'flex', flexDirection: 'column', alignItems: 'center',
      }}>
        {themeBg ? (
          <div style={{ position: 'absolute', left: 0, right: 0, top: 0, bottom: 46, backgroundImage: 'url(' + themeBg + ')', backgroundSize: '100% auto', backgroundPosition: 'bottom center', backgroundRepeat: 'no-repeat' }}></div>
        ) : (
          <React.Fragment>
            <div style={{ position: 'absolute', left: 0, right: 0, top: '58%', height: 7, background: '#CDB488', boxShadow: '0 2px 4px rgba(120,90,30,0.15)' }}></div>
            <div style={{ position: 'absolute', left: 0, right: 0, top: 'calc(58% + 7px)', bottom: 0, backgroundImage: 'repeating-linear-gradient(90deg, rgba(150,110,55,0.10) 0 1px, transparent 1px 60px)' }}></div>
            <RoomWindow th={null} style={{ top: 132, left: 18 }}></RoomWindow>
            <div style={{ position: 'absolute', left: '50%', bottom: 82, transform: 'translateX(-50%)', width: 190, height: 54, borderRadius: '50%', background: 'radial-gradient(ellipse at center, #F4C9A6 0%, #ECB890 60%, #E0A878 100%)', border: '3px solid #F7E7D2', boxShadow: '0 4px 10px rgba(120,90,30,0.15)' }}></div>
          </React.Fragment>
        )}
        <div style={{ position: 'absolute', top: 14, right: 14 }}>
          <Chip icon="water_drop" color={stage <= 2 ? BGC.skyDeep : BGC.orange} bg="rgba(255,255,255,0.9)">{st.n}단계 · {st.name}</Chip>
        </div>

        <div style={{ marginTop: 52, width: '82%' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, background: 'rgba(255,255,255,0.92)', borderRadius: 16, padding: '11px 15px', boxShadow: '0 3px 12px rgba(46,116,170,0.14)' }}>
            <MIcon name={stage >= 4 ? 'sentiment_dissatisfied' : (stage <= 1 ? 'sentiment_very_satisfied' : 'water_drop')} size={20} color={stage >= 4 ? BGC.orange : BGC.skyDeep}></MIcon>
            <span style={{ fontSize: 13, fontWeight: 700, color: BGC.ink, lineHeight: 1.35, textAlign: 'center', textWrap: 'pretty' }}>{st.msg}</span>
          </div>
        </div>

        <WanderingBangulee img={st.img} sprite={sprite} frames={frames} faces={faces} base={!equipped} costume={equipped} big={false} stage={stage} active={!editMode && stage <= 3} name={st.name} floor={96}></WanderingBangulee>

        {/* 편집 모드 안내 + 배치 경계선 */}
        {editMode && (
          <div style={{ position: 'absolute', left: 0, right: 0, top: DECOR_MIN_TOP, borderTop: '2px dashed rgba(46,116,170,0.55)', pointerEvents: 'none', zIndex: 20 }}>
            <span style={{ position: 'absolute', right: 8, top: -10, background: BGC.skyDeep, color: '#fff', fontSize: 10, fontWeight: 800, padding: '2px 8px', borderRadius: 99 }}>이 아래로 배치</span>
          </div>
        )}
        {editMode && (
          <div style={{ position: 'absolute', top: 52, left: '50%', transform: 'translateX(-50%)', background: 'rgba(20,50,80,0.82)', color: '#fff', fontSize: 12, fontWeight: 700, padding: '6px 13px', borderRadius: 99, zIndex: 25, whiteSpace: 'nowrap' }}>가구를 끌어 배치하세요</div>
        )}

        {placedItems.map(({ id, img, size }, idx) => {
          const def = DECOR_POS[id] || { left: 18 + (idx % 4) * 84, top: 300 + Math.floor(idx / 4) * 70 };
          const initial = (decorPos && decorPos[id]) || def;
          if (editMode) {
            return <DraggableDecor key={id} id={id} src={img} size={size} initial={initial} roomRef={roomRef} onEnd={onMoveDecor}></DraggableDecor>;
          }
          return <CleanImg key={id} src={img} alt="" style={{ position: 'absolute', left: initial.left, top: initial.top, height: size, width: 'auto', pointerEvents: 'none', filter: 'drop-shadow(0 3px 5px rgba(0,0,0,0.2))' }}></CleanImg>;
        })}

        <div style={{
          position: 'absolute', left: 0, right: 0, bottom: 0, padding: '10px 16px',
          background: barSkin.bg, backdropFilter: 'blur(3px)',
          display: 'flex', alignItems: 'center', gap: 10,
        }}>
          <span style={{ fontSize: 12.5, fontWeight: 800, color: barSkin.ink }}>촉촉도</span>
          <MoistureDots filled={moisture}></MoistureDots>
          <div style={{ flex: 1 }}></div>
          <Chip icon="local_fire_department" color="#C26A1B" bg="#FDEFD9">연속 {streak}일 기록</Chip>
        </div>
      </div>

      {/* 방 꾸미기 / 옷 갈아입기 */}
      <div style={{ display: 'flex', gap: 10, marginTop: 12 }}>
        <button className="press" onClick={() => setEditMode((v) => !v)} style={{ flex: 1, minHeight: 46, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, borderRadius: 16, cursor: 'pointer', background: editMode ? BGC.sky : '#fff', border: editMode ? 'none' : '1.5px solid #CBE6F8', boxShadow: '0 2px 6px rgba(46,116,170,0.12)' }}>
          <MIcon name={editMode ? 'check' : 'edit'} size={19} color={editMode ? '#fff' : BGC.skyDeep}></MIcon>
          <span className="jua" style={{ fontSize: 14.5, color: editMode ? '#fff' : BGC.skyDeep }}>{editMode ? '완료' : '방 꾸미기'}</span>
        </button>
        <button className="press" onClick={() => setCloset(true)} style={{ flex: 1, minHeight: 46, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, borderRadius: 16, cursor: 'pointer', background: '#fff', border: '1.5px solid #CBE6F8', boxShadow: '0 2px 6px rgba(46,116,170,0.12)' }}>
          <MIcon name="checkroom" size={19} color={BGC.skyDeep}></MIcon>
          <span className="jua" style={{ fontSize: 14.5, color: BGC.skyDeep }}>옷 갈아입기</span>
        </button>
      </div>

      {recorded && (
        <PrimaryBtn icon="edit" onClick={onEditToday} style={{ marginTop: 12 }}>오늘 기록 수정</PrimaryBtn>
      )}

      {/* 오늘 기록 — 물 가계부 제거됨 */}
      {false && (
      <div style={{ marginTop: 14 }}>
        {recorded ? (
          <Card>
            <SectionLabel icon="receipt_long" right={
              usage <= goal
                ? <Chip icon="check_circle" color="#2C8A60" bg="#E8F6EF">목표 달성!</Chip>
                : <Chip icon="error" color="#C26A1B" bg="#FDEFD9">목표 초과</Chip>
            }>오늘의 물 가계부</SectionLabel>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 6 }}>
              <span className="jua" style={{ fontSize: 38, color: BGC.skyDeep }}>{usage.toLocaleString()}L</span>
              <span style={{ fontSize: 13.5, fontWeight: 700, color: BGC.sub }}>/ 목표 {goal}L</span>
            </div>
            <div style={{ margin: '10px 0 12px' }}>
              <WaterBar value={usage} goal={goal}></WaterBar>
            </div>
            <div style={{ display: 'flex', gap: 7, flexWrap: 'wrap' }}>
              <Chip icon="bolt" color="#B8860B" bg="#FFF6D8">에너지 {BG.fmt1(e.total)}kWh</Chip>
              <Chip icon="co2" color="#2C8A60" bg="#E8F6EF">CO₂ {BG.fmt1(e.co2)}kg</Chip>
              <Chip icon="battery_charging_full" color={BGC.skyDeep}>폰 충전 {e.phoneCharges}회</Chip>
            </div>
          </Card>
        ) : (
          <Card style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
            <img src="data:image/png;base64," alt="방울이" style={{ height: 64 }}></img>
            <div style={{ flex: 1 }}>
              <div className="jua" style={{ fontSize: 17, color: BGC.ink }}>오늘 아직 기록 전이에요!</div>
              <div style={{ fontSize: 12.5, color: BGC.sub, marginTop: 2 }}>계량기를 찍으면 10초면 끝나요.</div>
              <PrimaryBtn icon="photo_camera" onClick={() => onNav('camera')} style={{ minHeight: 44, marginTop: 10, fontSize: 15.5 }}>계량기 촬영하기</PrimaryBtn>
            </div>
          </Card>
        )}
      </div>
      )}

      {/* 절약 팁 */}
      <Card style={{ marginTop: 12 }}>
        <SectionLabel icon="tips_and_updates" right={<Chip color="#C26A1B" bg="#FDEFD9">{tip.when}</Chip>}>방울이의 절약 팁</SectionLabel>
        <div style={{ fontSize: 13.5, color: BGC.ink, lineHeight: 1.6 }}>{tip.text}</div>
      </Card>

      {closet && <ClosetSheet owned={owned} equipped={equipped} onEquip={(id) => { onEquip(id); setCloset(false); }} onClose={() => setCloset(false)} onNav={onNav}></ClosetSheet>}
    </div>
  );
}

export default HomeScreen
